ArtifactKind = Literal[
    "surface",
    "regional_summary",
    "hotspot_manifest",
    "trend_surface",
    "trend_regional_summary",
    "trend_agreement_surface",
    "trend_agreement_summary",
    "classification_surface",
    "classification_regional_summary",
    "classification_hotspot_manifest",
